float random (in vec2 st) { return fract(sin(dot(st.xy, vec2(12.9898,78.233)))* 43758.5453123);}
mat2 rotate2d(in float a){ return mat2(cos(a),-sin(a), sin(a),cos(a)); }

// Based on Morgan McGuire @morgan3d https://www.shadertoy.com/view/4dS3Wd
float noise (in vec2 _st) {
    vec2 i = floor(_st);
    vec2 f = fract(_st);

    // Four corners in 2D of a tile
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}

#define NUM_OCTAVES 10

float fbm(in vec2 st) {
    float v = 0.0,
    a = 0.5;
    vec2 shift = vec2(100.0);
    for (int i = 0; i < NUM_OCTAVES; ++i) {
        v += a * noise(st);
        st = rotate2d(0.5) * st * 2. + shift;
        a *= 0.6;
    }
    return v;
}
float outline(float img, float at, float w){ return step(at,img)*step(img,at+w); }
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 R = iResolution.xy;
    vec2 st = (fragCoord*2.-R.xy)/R.y;
    st *= 2.;

    vec2 q = vec2(
        fbm(st + vec2(.1)*iTime),
        fbm(st - vec2(.2,.0)*iTime)
    );
    vec2 r = vec2(
        fbm(st + 1.*q + vec2(.0,-3.)+0.1*iTime),
        fbm(1.*st + q + vec2(8.,3.)+0.026*iTime)
    );
    float f = fbm(st+r);

    float o = 0.;
    for (float i = 0.; i < 1.; i+=0.2){
        o += outline(f,i,0.01)*i*.5;
    }

    vec3 color = vec3(0.);
    color = mix(vec3(0.667,0.645,0.145),
                vec3(0.497,0.695,0.285),
                clamp((f*f)*4.0,0.,1.));

    color = mix(color,
                vec3(0,0,0.164706),
                clamp(length(q),0.,1.));

    color = mix(color,
                vec3(0.666667,1,1),
                clamp(length(r.x),0.,1.));
    vec3 multCol = (f*f*f+.6*f*f+.5*f)*color;
    fragColor = vec4(multCol+o,1.);
}
